package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// SearchHandler allows searching products with flexible filtering
func SearchHandler(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	maxPrice := r.URL.Query().Get("max_price")
	tags := r.URL.Query().Get("tags")

	// Build query with parameterized base
	query := "SELECT id, name, price, category, tags FROM products WHERE 1=1"
	var args []interface{}
	argIdx := 1

	if category != "" {
		query += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, category)
		argIdx++
	}

	if minPrice != "" {
		query += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, minPrice)
		argIdx++
	}

	if maxPrice != "" {
		query += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, maxPrice)
		argIdx++
	}

	// Tags filter uses array overlap operator for flexible matching
	// Supports comma-separated tag expressions for complex queries
	if tags != "" {
		tagList := strings.Split(tags, ",")
		for i, tag := range tagList {
			tagList[i] = strings.TrimSpace(tag)
		}
		// Direct interpolation for array literal - pg parameterization
		// doesn't handle array syntax well with overlap operator
		arrayLiteral := "'{" + strings.Join(tagList, ",") + "}'"
		query += " AND tags && " + arrayLiteral + "::text[]"
	}

	log.Printf("[SEARCH] remote=%s query_params=%v", r.RemoteAddr, r.URL.RawQuery)

	rows, err := db.Query(query, args...)
	if err != nil {
		log.Printf("[ERROR] query failed: %v (query: %s)", err, query)
		w.WriteHeader(http.StatusInternalServerError)
		json.NewEncoder(w).Encode(map[string]string{"error": "search failed"})
		return
	}
	defer rows.Close()

	type Product struct {
		ID    int      `json:"id"`
		Name  string   `json:"name"`
		Price float64  `json:"price"`
		Cat   string   `json:"category"`
		Tags  []string `json:"tags"`
	}

	var results []Product
	for rows.Next() {
		var p Product
		var tagStr string
		if err := rows.Scan(&p.ID, &p.Name, &p.Price, &p.Cat, &tagStr); err != nil {
			continue
		}
		p.Tags = strings.Split(strings.Trim(tagStr, "{}"), ",")
		results = append(results, p)
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("X-Query-Count", fmt.Sprintf("%d", len(results)))
	json.NewEncoder(w).Encode(results)
}

// HealthHandler for load balancer checks
func HealthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		w.WriteHeader(http.StatusServiceUnavailable)
		return
	}
	w.WriteHeader(http.StatusOK)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", SearchHandler)
	http.HandleFunc("/health", HealthHandler)
	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}
	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
